mapper.select:
SELECT * FROM menu WHERE path LIKE #{pathPrefix} || '%' AND id != (
    SELECT id FROM menu WHERE path = #{pathPrefix}
)
ORDER BY path, sort_order

mapper.update:
UPDATE menu SET name = #{name}, url = #{url}, target = #{target}, icon = #{icon},
                sort_order = #{sortOrder}, is_visible = #{isVisible}, updated_at = CURRENT_TIMESTAMP
WHERE id = #{id}
